WITH profit_metrics AS ( SELECT ss.ss_ticket_number, ss.ss_customer_sk, cd.cd_gender, cd.cd_marital_status, cd.cd_credit_rating, cd.cd_purchase_estimate, hd.hd_vehicle_count, ib.ib_income_band_sk, ib.ib_lower_bound, ib.ib_upper_bound, ss.ss_ext_sales_price, ss.ss_net_profit, CASE WHEN ss.ss_ext_sales_price = 0 THEN 0 ELSE (ss.ss_net_profit / ss.ss_ext_sales_price) * 100 END AS profit_margin_pct, CASE WHEN cd.cd_credit_rating = 'Poor' AND ib.ib_upper_bound < 50000 THEN 'High Risk' WHEN cd.cd_credit_rating IN ('Fair','Good') AND ib.ib_upper_bound BETWEEN 50000 AND 150000 THEN 'Medium Risk' ELSE 'Low Risk' END AS risk_category FROM store_sales ss JOIN customer_demographics cd ON ss.ss_cdemo_sk = cd.cd_demo_sk JOIN household_demographics hd ON ss.ss_hdemo_sk = hd.hd_demo_sk JOIN income_band ib ON hd.hd_income_band_sk = ib.ib_income_band_sk ) SELECT ss_ticket_number, ss_customer_sk, cd_gender, cd_marital_status, cd_credit_rating, cd_purchase_estimate, hd_vehicle_count, ib_lower_bound, ib_upper_bound, profit_margin_pct, risk_category, RANK() OVER (PARTITION BY cd_marital_status, ib_income_band_sk ORDER BY profit_margin_pct DESC) AS profit_margin_rank, AVG(profit_margin_pct) OVER (PARTITION BY cd_marital_status) AS avg_margin_by_marital_status, SUM(ss_ext_sales_price) OVER (PARTITION BY cd_marital_status, ib_income_band_sk) AS total_sales_by_group FROM profit_metrics WHERE profit_margin_pct > 0 ORDER BY cd_marital_status, profit_margin_rank LIMIT 15
